    ('0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26a-s001:0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start -3000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3'::uuid, 'period_start', '-4500', '-3000', 'fields-wd1-2026-09-26a-s001:0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-4500'' -> ''-3000''', '[{"source": "https://www.miglus.de/projects/Tell-Harmal/tell-harmal.html", "url": "https://www.miglus.de/projects/Tell-Harmal/tell-harmal.html", "quote": "Finally, the expedition executed few deeper soundings and found traces of three or four building levels from the 3rd millennium BC. As a result of this work we know that the town existed already in the Akkadian Period.", "outcome": "found"}, {"source": "https://indroyc.com/2020/07/17/shaduppum-the-forgotten-city-that-whispered-civilization/", "url": "https://indroyc.com/2020/07/17/shaduppum-the-forgotten-city-that-whispered-civilization/", "quote": "The city first emerged during the days of Sargon of Akkad in the late third millennium BCE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The excavator Peter Miglus reports building levels of the 3rd millennium BC showing the town existed in the Akkadian period, and a second account puts its emergence in the late third millennium BCE; the start therefore lies in the 3000 - 1500 BC bucket, not 4500 - 3000 BC, written as the millennium''s first year, -3000.", "value_page": null}]'::jsonb),
    ('0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3'::uuid, 'site_type', 'Fortress/citadel', 'City/town/settlement', 'fields-wd1-2026-09-26a-s001:0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Fortress/citadel'' -> ''City/town/settlement''', '[{"source": "https://www.miglus.de/projects/Tell-Harmal/1998/1998.html", "url": "https://www.miglus.de/projects/Tell-Harmal/1998/1998.html", "quote": "Under the new domination this small city was given another place in the political and administrative system.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Shaduppum", "url": "https://en.wikipedia.org/wiki/Shaduppum", "quote": "It was an administrative center for the kingdom and its name means \"the treasury.\"", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Shaduppum", "url": "https://en.wikipedia.org/wiki/Shaduppum", "quote": "The tutelary deity of the city was Bēl-gašer.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "CONFLICT", "reasoning": "Tell Harmal is the mound of the walled town of Shaduppum with private houses, eight temples and an administrative building; its wall is only one phase of a small city, which both the excavator and Wikipedia call a city, so City/town/settlement replaces Fortress/citadel.", "value_page": null}]'::jsonb),
