    ('0d9bd81d-d41c-4381-8e2e-7626928fedc1'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26a-s001:0d9bd81d-d41c-4381-8e2e-7626928fedc1:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "The only readable dated statements (3600-2700 BC) come from the Wikipedia family and its copies; the scholarly dating of Apolianka to the phase after 3650-3550 BC (Hofmann et al., Antiquity 2024) sits on a page the checker cannot read, and the JNA survey report gives only Tripolye phases C1/C2 without a year, so no two independent sources can be quoted for the start.", "value_page": null}]'::jsonb),
    ('0d9bd81d-d41c-4381-8e2e-7626928fedc1'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Apolyanka', NULL, 'fields-wd1-2026-09-26a-s001:0d9bd81d-d41c-4381-8e2e-7626928fedc1:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''https://en.wikipedia.org/wiki/Apolyanka'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article no longer exists, the Ukrainian and Wikidata entries describe the modern village, and the scholarly pages treat Apolianka only as one section of multi-site reports (or sit behind pages the checker cannot read), so no loadable page about this site itself can be named.", "value_page": null}]'::jsonb),
    ('0de3da9b-5aeb-45a2-8f72-31ac1ad74a13'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26a-s001:0de3da9b-5aeb-45a2-8f72-31ac1ad74a13:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('0de3da9b-5aeb-45a2-8f72-31ac1ad74a13'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26a-s001:0de3da9b-5aeb-45a2-8f72-31ac1ad74a13:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "clear", "status": "MISSING", "reasoning": "The Beeley Moor cairns and cairnfields are Bronze Age; only the Derbyshire HER gives a dated statement (''second millennium BC'', ''early 2nd millennium BC''), while Wikipedia and the other readable pages say only ''Bronze Age'' or ''over 3,000 years old''. No second independent source dates the start, and the stored -4500 (Neolithic) is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('0de3da9b-5aeb-45a2-8f72-31ac1ad74a13'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Beeley_Moor', 'https://her.derbyshire.gov.uk/Monument/MDR10069', 'fields-wd1-2026-09-26a-s001:0de3da9b-5aeb-45a2-8f72-31ac1ad74a13:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Beeley_Moor'' -> ''https://her.derbyshire.gov.uk/Monument/MDR10069''', '[{"source": "https://her.derbyshire.gov.uk/Monument/MDR10069", "url": "https://her.derbyshire.gov.uk/Monument/MDR10069", "quote": "MDR10069 - Cairns, Hell Bank Plantation, Beeley Moor, Beeley", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q17676229", "url": "https://www.wikidata.org/wiki/Q17676229", "quote": "Two cairns on Beeley Moor, east of Hell Bank Plantation", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the hill (''Hill in the Peak District of England'') and gives the cairns two sentences. The Derbyshire Historic Environment Record entry for the scheduled cairns on Beeley Moor, 0.17 km from the stored point, is a readable heritage register page about the cairn site itself, and Wikidata''s item for the same scheduled monument names it too.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('0e7825f5-26f0-483e-8cd0-687a9228a894'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Temples_(band)', 'https://en.wikipedia.org/wiki/Stabiae', 'fields-wd1-2026-09-26a-s001:0e7825f5-26f0-483e-8cd0-687a9228a894:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Temples_(band)'' -> ''https://en.wikipedia.org/wiki/Stabiae''', '[{"source": "https://en.wikipedia.org/wiki/Stabiae", "url": "https://en.wikipedia.org/wiki/Stabiae", "quote": "The settlement at Stabiae arose from as early as the 7th century BC", "outcome": "found"}, {"source": "https://pompeiisites.org/en/exhibitions/in-search-of-stabiae/", "url": "https://pompeiisites.org/en/exhibitions/in-search-of-stabiae/", "quote": "In ancient times, it marked the southern boundary of Stabiae and it was in a strategic position to control the routes connecting the Sarno", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the article on the band Temples, another item; the English Wikipedia article Stabiae is about this ancient town near Castellammare di Stabia, which the Archaeological Park of Pompeii also describes.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Stabiae", "unreadable": false, "wikibase_item": "Q547910"}}]'::jsonb),
    ('10f42fef-61bd-46a1-b2e7-f35e0c84f9b4'::uuid, 'site_type', 'Megalithic structures', 'Monument', 'fields-wd1-2026-09-26a-s001:10f42fef-61bd-46a1-b2e7-f35e0c84f9b4:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Megalithic structures'' -> ''Monument''', '[{"source": "https://delphi.culture.gr/treasure-sikionion/", "url": "https://delphi.culture.gr/treasure-sikionion/", "quote": "The monument was built at a prominent spot, visible from the entrance to the sanctuary of Apollo.", "outcome": "found"}, {"source": "https://www.perseus.tufts.edu/hopper/artifact?name=Delphi,%20Treasury%20of%20the%20Sikyonians%20(III)&object=Building", "url": "https://www.perseus.tufts.edu/hopper/artifact?name=Delphi,%20Treasury%20of%20the%20Sikyonians%20(III)&object=Building", "quote": "Temple-like building; the 1st treasury from the entrance to the Sanctuary of Apollo, on the south side of the Sacred Way, west of the Offering of the Tarentines.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Sicyonian Treasury is a small Doric votive treasury building on the Sacred Way at Delphi, which the Ephorate calls a monument and Perseus a temple-like treasury; it is not a megalithic structure, and with no canonical ''treasury'' type and no temple in the strict sense, Monument is the most specific type that holds.", "value_page": null}]'::jsonb),
    ('1327e266-b4d2-484a-a6c8-f165ec0e0716'::uuid, 'geom', '0101000020E6100000810471DBC0A82D40E8B45FCDCF934B40', 'SRID=4326;POINT(15.011062 55.026589)', 'fields-wd1-2026-09-26a-s001:1327e266-b4d2-484a-a6c8-f165ec0e0716:geom', 'fields-wd1-2026-09-26a-s001 (wd1-point): 55.15477912114312, 14.829596383615582 -> 55.026589, 15.011062', '[{"source": "https://www.wikidata.org/wiki/Q4098628", "url": "https://www.wikidata.org/wiki/Q4098628", "quote": "55°1''35.8\"N, 15°0''39.8\"E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=44432", "url": "https://www.megalithic.co.uk/article.php?sid=44432", "quote": "Latitude: 55.025612N Longitude: 15.010848E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikidata and the Megalithic Portal both put Rispebjerg on the plateau above Øleådalen near Pedersker in south Bornholm (55.0266, 15.0111 and 55.0256, 15.0108, 0.1 km apart; OpenStreetMap''s archaeological-site polygon agrees). The stored point (55.1548, 14.8296) is about 18 km away in west Bornholm, and the English Wikipedia point (14.019 E) lies in the sea, so the point is replaced.", "value_page": null}]'::jsonb),
