    ('174016a6-75a8-416d-b0e5-e316b4f96330'::uuid, 'period_start', '-4500', '-2300', 'fields-wd1-2026-09-26a-s001:174016a6-75a8-416d-b0e5-e316b4f96330:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-4500'' -> ''-2300''', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=372", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=372", "quote": "The monument comprises the remains of a stone alignment, probably dating to the Bronze Age (c.2300 BC - 800 BC).", "outcome": "found"}, {"source": "https://www.transceltic.com/wales/harolds-stones-trellech", "url": "https://www.transceltic.com/wales/harolds-stones-trellech", "quote": "Harold''s Stones are a row of three large standing stones dating to the Bronze Age (c. 2150-800 BC).", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "Cadw''s scheduled-monument record MM017 for Harold''s Stones at Trellech dates the stone alignment to the Bronze Age, c. 2300-800 BC, and Transceltic independently dates the row to the Bronze Age, c. 2150-800 BC; both put its start in the 3000-1500 BC bucket, not the Early Neolithic -4500 stored. The stones have not been dated by excavation, so the start is the register''s Bronze Age bound; popular pages giving c. 1500 BC or ''3,500 years'' fall inside that range.", "value_page": null}]'::jsonb),
    ('174016a6-75a8-416d-b0e5-e316b4f96330'::uuid, 'site_type', 'Megalithic stones', 'Standing stone', 'fields-wd1-2026-09-26a-s001:174016a6-75a8-416d-b0e5-e316b4f96330:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Megalithic stones'' -> ''Standing stone''', '[{"source": "https://archwilio.org.uk/her/chi3/report/page.php?watprn=GGAT00854g", "url": "https://archwilio.org.uk/her/chi3/report/page.php?watprn=GGAT00854g", "quote": "Site Type (preferred type first) : Prehistoric - cup marked stone / Bronze Age - Standing stone", "outcome": "found"}, {"source": "http://www.stone-circles.org.uk/stone/haroldsstones.htm", "url": "http://www.stone-circles.org.uk/stone/haroldsstones.htm", "quote": "To the southwest of the village of Trellech are three large standing stones in a 12 metre alignment", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Glamorgan-Gwent Historic Environment Record types the monument as Bronze Age standing stones and stone-circles.org.uk describes three large standing stones in an alignment; Standing stone is more specific than the generic Megalithic stones.", "value_page": null}]'::jsonb),
    ('174016a6-75a8-416d-b0e5-e316b4f96330'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Trellech', 'https://de.wikipedia.org/wiki/Harold%E2%80%99s_Stones', 'fields-wd1-2026-09-26a-s001:174016a6-75a8-416d-b0e5-e316b4f96330:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Trellech'' -> ''https://de.wikipedia.org/wiki/Harold%E2%80%99s_Stones''', '[{"source": "https://de.wikipedia.org/wiki/Harold%E2%80%99s_Stones", "url": "https://de.wikipedia.org/wiki/Harold%E2%80%99s_Stones", "quote": "Die Harold’s Stones (auch Trellech, Triligh oder Trelleck Stones genannt) bei Trellech in Monmouthshire in Wales sind eine als Scheduled Monument geschützte", "outcome": "found"}, {"source": "https://archwilio.org.uk/her/chi3/report/page.php?watprn=GGAT00854g", "url": "https://archwilio.org.uk/her/chi3/report/page.php?watprn=GGAT00854g", "quote": "Harold''s Stones, Trellech Primary Reference Number (PRN) : 00854g", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is the village of Trellech (Harold''s Stones only redirects there); the German Wikipedia has an article on Harold''s Stones themselves, and the regional Historic Environment Record names the same monument.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Harold’s Stones", "unreadable": false, "wikibase_item": "Q20600396"}}]'::jsonb),
