    ('1baa447b-94b2-4081-9a54-f699005efcc5'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26a-s001:1baa447b-94b2-4081-9a54-f699005efcc5:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "clear", "status": "MISSING", "reasoning": "Sources only call it an ''Iron Age or late Bronze Age hill fort'' (Wikipedia) or ''Iron Age?'' (Roman Britain); the only dated statement found is Historic England''s generic range for the whole class of large multivallate hillforts, not a date for this fort. No two sources date this hillfort''s construction, so the stored -1500 is emptied.", "value_page": null}]'::jsonb),
    ('1baa447b-94b2-4081-9a54-f699005efcc5'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26a-s001:1baa447b-94b2-4081-9a54-f699005efcc5:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://www.roman-britain.co.uk/places/caer_caradoc_church_stretton/", "url": "https://www.roman-britain.co.uk/places/caer_caradoc_church_stretton/", "quote": "A long, narrow (2.5ha) fort of the Cornovii", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4931", "url": "https://www.megalithic.co.uk/article.php?sid=4931", "quote": "Caer Caradoc is a breathtaking location for a hillfort around the summit of this prominent hill to the south of Shrewsbury.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Caer_Caradoc", "url": "https://en.wikipedia.org/wiki/Caer_Caradoc", "quote": "or late Bronze Age hill fort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "Every source describes the site as a hillfort (a ramparted hill fort of the Cornovii), never as a fortress or citadel; the most specific canonical type for a hillfort is Fort.", "value_page": null}]'::jsonb),
    ('1baa447b-94b2-4081-9a54-f699005efcc5'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Caer_Caradoc', 'https://www.megalithic.co.uk/article.php?sid=4931', 'fields-wd1-2026-09-26a-s001:1baa447b-94b2-4081-9a54-f699005efcc5:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Caer_Caradoc'' -> ''https://www.megalithic.co.uk/article.php?sid=4931''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=4931", "url": "https://www.megalithic.co.uk/article.php?sid=4931", "quote": "Site Name: Caer Caradoc (Church Stretton)", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q5016860", "url": "https://www.wikidata.org/wiki/Q5016860", "quote": "Iron Age hillfort near Church Stretton, Shropshire, England, UK", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is explicitly about the hill (''This article is about the hill above Church Stretton'') and mentions the fort in one sentence; there is no Wikipedia article on the hillfort itself, and the Historic England list entry cannot be read without a browser. The Megalithic Portal entry is a readable page devoted to the Caer Caradoc (Church Stretton) hillfort, and the hillfort''s own Wikidata item confirms the same site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('1bc69a3e-2ded-4f53-b96e-38811edee56a'::uuid, 'period_name', '500 BC - 1 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26a-s001:1bc69a3e-2ded-4f53-b96e-38811edee56a:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start -3000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1bc69a3e-2ded-4f53-b96e-38811edee56a'::uuid, 'period_start', '-500', '-3000', 'fields-wd1-2026-09-26a-s001:1bc69a3e-2ded-4f53-b96e-38811edee56a:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-500'' -> ''-3000''', '[{"source": "https://aze.media/nakhchivan-a-cultural-cradle-of-azerbaijan/", "url": "https://aze.media/nakhchivan-a-cultural-cradle-of-azerbaijan/", "quote": "there existed city type settlements, including: Shahtakhti, Gizilburun and Garabaghlar, established in the 2nd – 3rd Millennium BC", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/%C5%9Eahtaxt%C4%B1", "url": "https://en.wikipedia.org/wiki/%C5%9Eahtaxt%C4%B1", "quote": "Nearby is the site of an ancient settlement of the Bronze and first Iron Age; it is located south-west from the village. According to findings, the earliest settlement in the area was founded in the third millennium BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "Aze.media counts Shahtakhti among Nakhchivan''s city-type settlements established in the 3rd-2nd millennium BC, and Wikipedia (the Şahtaxtı article; the Russian Govurqala article likewise says ''III—II тысячелетий до н. э.'') dates the founding of the Bronze and Early Iron Age settlement by Şahtaxtı to the third millennium BC; the start is -3000, not the stored 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
    ('1be281ba-d8dd-4260-85c9-39aa02b15567'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26a-s001:1be281ba-d8dd-4260-85c9-39aa02b15567:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start -500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1be281ba-d8dd-4260-85c9-39aa02b15567'::uuid, 'period_start', '-1000', '-500', 'fields-wd1-2026-09-26a-s001:1be281ba-d8dd-4260-85c9-39aa02b15567:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-1000'' -> ''-500''', '[{"source": "https://ulasnews.com/2020/12/29/burrough-hill-iron-age-hillfort-self-guided-walk/", "url": "https://ulasnews.com/2020/12/29/burrough-hill-iron-age-hillfort-self-guided-walk/", "quote": "The Park is also the location of one of Leicestershire’s finest prehistoric monuments, Burrough Hill Iron Age hillfort. Dating is not certain, but the hillfort was probably established in the 5th century BC, on the end of a high promontory approximately 200m above sea level.", "outcome": "found"}, {"source": "https://www.nbcnews.com/id/wbna55504978", "url": "https://www.nbcnews.com/id/wbna55504978", "quote": "The fort, called Burrough Hill, was carved into the side of a 690-foot (210 meters) mound in the modern-day English county of Leicestershire during the Iron Age, around 500 B.C., and was used until the third or fourth century A.D. of the Roman period.", "outcome": "found"}, {"source": "https://www.sciencedaily.com/releases/2014/06/140623092301.htm", "url": "https://www.sciencedaily.com/releases/2014/06/140623092301.htm", "quote": "The hillfort appears to have been constructed during the Iron Age, around 500 BC, and used throughout the later Iron Age and into the Roman period.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The University of Leicester excavators (ULAS, 2010-2014 project) date the founding of Burrough Hill hillfort to the 5th century BC / around 500 BC, and Live Science (syndicated by NBC News) reports the same c. 500 BC construction. The earlier Neolithic/Bronze Age finds on the promontory predate the hillfort itself; the stored -1000 (1500-500 BC) and Wikidata''s AD 500 are both wrong, so the start becomes -500.", "value_page": null}]'::jsonb),
    ('21ba0be2-3da7-40f7-8f99-aece38b3ea17'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/White_Sheet_Hill', 'https://www.megalithic.co.uk/article.php?sid=5105', 'fields-wd1-2026-09-26a-s001:21ba0be2-3da7-40f7-8f99-aece38b3ea17:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/White_Sheet_Hill'' -> ''https://www.megalithic.co.uk/article.php?sid=5105''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=5105", "url": "https://www.megalithic.co.uk/article.php?sid=5105", "quote": "An extensive site just to the north of the town of Mere, Wiltshire and visible from the A303. It comprises a neolithic causewayed camp, a series of Bronze Age barrows and a large Iron Age hill fort.", "outcome": "found"}, {"source": "https://www.hiddenwiltshire.com/post/white-sheet-hill-mere", "url": "https://www.hiddenwiltshire.com/post/white-sheet-hill-mere", "quote": "White Sheet Hill is interesting for its diverse archaeological heritage.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill (downland, SSSI, flying club) with only a short archaeology section; the Megalithic Portal''s Whitesheet Hill entry is about the prehistoric site itself - the causewayed camp, the Bronze Age barrows and the hillfort - which Hidden Wiltshire also describes on White Sheet Hill near Mere; no Wikipedia article or readable register entry covers the barrows.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('2cce98a2-9851-42c7-9e9e-47f39b12be9c'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26a-s001:2cce98a2-9851-42c7-9e9e-47f39b12be9c:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2cce98a2-9851-42c7-9e9e-47f39b12be9c'::uuid, 'period_start', '-2000', NULL, 'fields-wd1-2026-09-26a-s001:2cce98a2-9851-42c7-9e9e-47f39b12be9c:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-2000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the site itself: it has never been excavated (''No excavations, hence undated''), Wikipedia calls its status as a hillfort disputed, and the Dorset HER and National Trust records only assign the generic Iron Age span of the monument class (800 BC onwards); nothing supports the stored -2000, and a class span is not an attested start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('2cce98a2-9851-42c7-9e9e-47f39b12be9c'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26a-s001:2cce98a2-9851-42c7-9e9e-47f39b12be9c:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO532", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO532", "quote": "A large univallate hillfort on the top of a narrow hill.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Lewesdon_Hill", "url": "https://en.wikipedia.org/wiki/Lewesdon_Hill", "quote": "Hill and hill fort in south west Dorset, England", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=25050", "url": "https://www.megalithic.co.uk/article.php?sid=25050", "quote": "Type: Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Dorset HER, Wikipedia and the Megalithic Portal describe the site as a (univallate) hillfort on the hilltop, so the most specific canonical type is Fort rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('2cce98a2-9851-42c7-9e9e-47f39b12be9c'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Lewesdon_Hill', 'https://heritage.dorsetcouncil.gov.uk/Monument/MDO532', 'fields-wd1-2026-09-26a-s001:2cce98a2-9851-42c7-9e9e-47f39b12be9c:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Lewesdon_Hill'' -> ''https://heritage.dorsetcouncil.gov.uk/Monument/MDO532''', '[{"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO532", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO532", "quote": "An earthwork encircling the narrow top of Lewesdon Hill, and interpreted as an Iron Age hillfort.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=25050", "url": "https://www.megalithic.co.uk/article.php?sid=25050", "quote": "Site Name: Lewesdon Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill (geography, access, a 1942 air crash) with only a paragraph on the disputed fort, and no Wikipedia article on the hillfort exists; the Dorset Historic Environment Record entry MDO532 is the heritage register record of the hillfort itself, which the Megalithic Portal also names as Lewesdon Hillfort.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('2ce50a62-f812-4204-bbb6-892a581fee52'::uuid, 'site_type', 'Earthwork', 'Fortification', 'fields-wd1-2026-09-26a-s001:2ce50a62-f812-4204-bbb6-892a581fee52:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Earthwork'' -> ''Fortification''', '[{"source": "https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)", "url": "https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)", "quote": "Based on excavations, the fortifications were originally built in the pre-Roman Iron Age", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)", "url": "https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)", "quote": "The Amelungsburg is a former ringfort that is located on the Amelungsberg hill on the Süntel ridge in the district of Hameln-Pyrmont in the German state of Lower Saxony.", "outcome": "found"}, {"source": "https://www.ms-visucom.de/cgi-bin/ebidat.pl?m=h&id=6008", "url": "https://www.ms-visucom.de/cgi-bin/ebidat.pl?m=h&id=6008", "quote": "Im Frühmittelalter wiederverwendete eisenzeitliche Wallburg", "outcome": "found"}, {"source": "https://www.ms-visucom.de/cgi-bin/ebidat.pl?id=6008", "url": "https://www.ms-visucom.de/cgi-bin/ebidat.pl?id=6008", "quote": "Die ursprüngliche Befestigung wurde nach dem 14C-Datum von Knochen in der Wallschüttung um 400 v. Chr. aufgeschüttet.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls the Amelungsburg a former ringfort whose fortifications were built in the pre-Roman Iron Age, and the European Castle Institute''s EBIDAT describes it as an Iron Age Wallburg (rampart fortification, classed as ring rampart and refuge fort) whose original Befestigung (fortification) dates to c. 400 BC. Fortification describes the site more specifically than the stored Earthwork.", "value_page": null}]'::jsonb),
