    ('30cf4488-c74c-42d8-8e21-a017ca0bf921'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26a-s001:30cf4488-c74c-42d8-8e21-a017ca0bf921:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
