    ('3209dfdf-ca19-45aa-b3a1-29815b5f5726'::uuid, 'period_start', '-1000', '-500', 'fields-wd1-2026-09-26a-s001:3209dfdf-ca19-45aa-b3a1-29815b5f5726:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-1000'' -> ''-500''', '[{"source": "https://travelpoi.com/place/55bb4e1e-449d-11f1-ae3f-005056332319/din-sylwy-bwrdd-arthur", "url": "https://travelpoi.com/place/55bb4e1e-449d-11f1-ae3f-005056332319/din-sylwy-bwrdd-arthur", "quote": "The hillfort itself was constructed and occupied during the Iron Age, broadly between around 500 BCE and the Roman period", "outcome": "found"}, {"source": "https://heneb.org.uk/hcla/penmon/area-8-din-sylwy-limestone-ridge-prn-33474/", "url": "https://heneb.org.uk/hcla/penmon/area-8-din-sylwy-limestone-ridge-prn-33474/", "quote": "these are not an indication of the fort’s construction, which should fall within the mid to late first millennium BC.", "outcome": "found"}, {"source": "https://archwilio.org.uk/her/chi3/report/page.php?watprn=GAT2595", "url": "https://archwilio.org.uk/her/chi3/report/page.php?watprn=GAT2595", "quote": "Other finds from molehills in the interior included Iron Age type ring-headed pins which are dated to 300-200 BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "MISSING", "reasoning": "Heneb (the Welsh archaeological trust) places the fort''s construction in the mid to late first millennium BC, its HER dates the earliest finds (ring-headed pins) to 300-200 BC, and TravelPOI gives construction from around 500 BCE; only Cadw''s generic Iron Age span (c. 800 BC - AD 74) reaches earlier and nothing supports a start around 1000 BC, so the start moves to c. 500 BC.", "value_page": null}]'::jsonb),
    ('3209dfdf-ca19-45aa-b3a1-29815b5f5726'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26a-s001:3209dfdf-ca19-45aa-b3a1-29815b5f5726:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://coflein.gov.uk/en/sites/93842", "url": "https://coflein.gov.uk/en/sites/93842", "quote": "A stone-walled fort occupies the summit of a prominent isolated cliff-girt limestone plateau.", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2514", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2514", "quote": "The monument comprises the remains of a hillfort situated on top of a flat-topped, steep-sided limestone hill", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "CONFLICT", "reasoning": "The RCAHMW record (Coflein) describes Din Sylwy as a stone-walled fort and Cadw''s scheduling report as a hillfort; Fort is the canonical type that holds, while nothing calls it a fortress or citadel.", "value_page": null}]'::jsonb),
