    ('424eed88-76e7-402b-8d62-3f598eb9c9ce'::uuid, 'period_start', '1', '-500', 'fields-wd1-2026-09-26a-s001:424eed88-76e7-402b-8d62-3f598eb9c9ce:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''1'' -> ''-500''', '[{"source": "https://www.burgasmuseums.bg/en/encdetail/aqaue-calidae-24", "url": "https://www.burgasmuseums.bg/en/encdetail/aqaue-calidae-24", "quote": "by the middle of the 1st millennium BC, people have been using the unique combination of hot springs with healing mud of the nearby lake Atanasovsko and the salty sea water.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Aquae_Calidae,_Bulgaria", "url": "https://en.wikipedia.org/wiki/Aquae_Calidae,_Bulgaria", "quote": "the oldest from Apollonia Pontica from the 5th century BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "The Burgas Regional Museum, which excavated the site, dates the use of the springs at the Thracian sanctuary of the Three Nymphs to the middle of the 1st millennium BC, and Wikipedia dates the oldest of the 4,000 coins found there to the 5th century BC; the Neolithic settlements it mentions lay only close by. The start, c. 500 BC, is before the Roman baths (72 BC onward) and outside the stored 1 - 500 AD bucket.", "value_page": null}]'::jsonb),
    ('424eed88-76e7-402b-8d62-3f598eb9c9ce'::uuid, 'site_type', 'Bath', 'City/town/settlement', 'fields-wd1-2026-09-26a-s001:424eed88-76e7-402b-8d62-3f598eb9c9ce:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Bath'' -> ''City/town/settlement''', '[{"source": "https://en.wikipedia.org/wiki/Aquae_Calidae,_Bulgaria", "url": "https://en.wikipedia.org/wiki/Aquae_Calidae,_Bulgaria", "quote": "was an ancient town in Thrace located in the territory of today''s Bulgarian port city of Burgas on the Black Sea.", "outcome": "found"}, {"source": "https://www.burgasmuseums.bg/en/encdetail/aqaue-calidae-24", "url": "https://www.burgasmuseums.bg/en/encdetail/aqaue-calidae-24", "quote": "Aquae Calidae – Therma, the city of the hot mineral baths", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Burgas Regional Museum describe Aquae Calidae as an ancient town (Therma/Thermopolis) built around the mineral baths, walled under Justinian, not only a bath building, so City/town/settlement is the type.", "value_page": null}]'::jsonb),
