    ('4ce83e01-a19d-40d0-a739-d6b571b9e824'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26a-s001:4ce83e01-a19d-40d0-a739-d6b571b9e824:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "clear", "status": "MISSING", "reasoning": "The Greek city was founded in the 3rd century BC (Wikipedia) or after 190 BC by Eumenes II (Treccani), but that is not the site''s start: Wikipedia reports Iron Age settlement structures found in 2016 and a Phrygian temple of Cybele built probably in the first half of the 7th century BC, and D''Andria (Colloquium Anatolicum 16) reports a pre-Greek Phrygian stepped altar and a 6th-century BC vessel at the Ploutonion. Only the Wikipedia family dates that pre-Greek start (the 7th-century phrase elsewhere is copied from it, and the D''Andria PDF is not reliably quotable), so no two independent sources date the site''s first occupation and the stored Hellenistic-bucket -500 cannot be kept.", "value_page": null}]'::jsonb),
    ('4d446438-7613-43d2-b95e-c6f1acf9109d'::uuid, 'geom', '0101000020E61000009BF3CFA0C42E5640CEB152CF273F4840', 'SRID=4326;POINT(88.3954 49.334)', 'fields-wd1-2026-09-26a-s001:4d446438-7613-43d2-b95e-c6f1acf9109d:geom', 'fields-wd1-2026-09-26a-s001 (wd1-point): 48.49340240037746, 88.73075123126766 -> 49.334, 88.3954', '[{"source": "https://www.wikidata.org/wiki/Q7849290", "url": "https://www.wikidata.org/wiki/Q7849290", "quote": "49°20''2.400\"N, 88°23''43.440\"E", "outcome": "found"}, {"source": "https://www.pilgrimmap.com/site/tsagaan-salaa-baga-oigor-petroglyphs", "url": "https://www.pilgrimmap.com/site/tsagaan-salaa-baga-oigor-petroglyphs", "quote": "49.3340, 88.3954", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikidata''s item for the Tsagaan Salaa rock art (UNESCO component 1382-001, Tsagaan Salaa-Baga Oigor, Ulaankhus soum) and Pilgrim Map''s page for the same component, which takes its location from the UNESCO component maps, both put the site at 49.334 N, 88.3954 E, at the confluence of the Tsagaan Salaa and Baga Oigor valleys (GeoNames puts the Tsagaan Salaa stream at 49.33 N, 88.35 E). The stored point 48.493, 88.731 lies about 96 km further south and is not the site.", "value_page": null}]'::jsonb),
