    ('4d446438-7613-43d2-b95e-c6f1acf9109d'::uuid, 'period_name', '< 4500 BC', NULL, 'fields-wd1-2026-09-26a-s001:4d446438-7613-43d2-b95e-c6f1acf9109d:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4d446438-7613-43d2-b95e-c6f1acf9109d'::uuid, 'period_start', '-11000', NULL, 'fields-wd1-2026-09-26a-s001:4d446438-7613-43d2-b95e-c6f1acf9109d:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-11000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0008)", "decision": "clear", "status": "MISSING", "reasoning": "UNESCO dates the earliest images of the three-site property only in years BP (Late Pleistocene to Early Holocene), the site''s own Wikipedia article says only ''Neolithic to the Bronze Age'', and the lone ''11,000 BCE'' (English Wikipedia''s World Heritage list) looks like a BP conversion and has no independent second source; no two independent sources date the start of this site with a year.", "value_page": null}]'::jsonb),
    ('50f9ccc8-06b1-4283-af88-a6769d0b9083'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26a-s001:50f9ccc8-06b1-4283-af88-a6769d0b9083:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('50f9ccc8-06b1-4283-af88-a6769d0b9083'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26a-s001:50f9ccc8-06b1-4283-af88-a6769d0b9083:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "clear", "status": "MISSING", "reasoning": "The Nine Stones have never been excavated and no readable source dates their construction with a year, century or millennium: Wikipedia says only that the circle was likely erected during the Bronze Age, the Dorset HER calls it late Neolithic or early Bronze Age, and English Heritage gives ''around 4,000 years ago'' plus a generic 2500-1000 BC range for stone circles in England. The stored -4500 is far too early, and without two sources dating this circle the field is emptied.", "value_page": null}]'::jsonb),
    ('55231dfd-fc7a-4bdf-a490-7ee5de43e975'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26a-s001:55231dfd-fc7a-4bdf-a490-7ee5de43e975:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('55231dfd-fc7a-4bdf-a490-7ee5de43e975'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26a-s001:55231dfd-fc7a-4bdf-a490-7ee5de43e975:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the Cornish guides place Boleigh Fogou only in the Iron Age / Romano-British period (Iron Age pottery, an early Iron Age house found by Time Team); no source gives this fogou a construction year, century or millennium, and ''around three thousand years old'' is not a readable date. The stored -1000 is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('55231dfd-fc7a-4bdf-a490-7ee5de43e975'::uuid, 'site_type', 'Infrastructure', 'Cave Structures', 'fields-wd1-2026-09-26a-s001:55231dfd-fc7a-4bdf-a490-7ee5de43e975:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Infrastructure'' -> ''Cave Structures''', '[{"source": "http://www.rosemerrynwood.co.uk/fogou.html", "url": "http://www.rosemerrynwood.co.uk/fogou.html", "quote": "Found to be part of an iron-age site, this man made underground cave has survived pretty well intact for 2000 years.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=582", "url": "https://www.megalithic.co.uk/article.php?sid=582", "quote": "Site Name: Boleigh Fogou Country: England County: Cornwall Type: Souterrain (Fogou, Earth House)", "outcome": "found"}, {"source": "https://www.cornwalls.co.uk/history/sites/boleigh_fogou.htm", "url": "https://www.cornwalls.co.uk/history/sites/boleigh_fogou.htm", "quote": "Boleigh Fougou is one of the better examples of these mysterious underground tunnels, although the roof has collapsed at the end of the main passage.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "replace", "status": "CONFLICT", "reasoning": "Boleigh Fogou is an Iron Age fogou, a man-made underground stone-lined passage (souterrain): Rosemerryn describes it as a man-made underground cave, the Megalithic Portal types it as a souterrain, the Cornwall Guide as an underground tunnel. Nothing makes it infrastructure; the most specific canonical type for an artificial underground chamber is Cave Structures.", "value_page": null}]'::jsonb),
    ('611a3218-4df9-4018-8d46-c1e731f04b2a'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26a-s001:611a3218-4df9-4018-8d46-c1e731f04b2a:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('611a3218-4df9-4018-8d46-c1e731f04b2a'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26a-s001:611a3218-4df9-4018-8d46-c1e731f04b2a:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "clear", "status": "MISSING", "reasoning": "Only Burnham-On-Sea.com gives a year (''defences of the Hill Fort were constructed about 300 BC''); Wikipedia''s Somerset list calls it Bronze Age and the heritage record only ''latter part of the Iron Age''. No second independent source dates the hillfort''s construction, and the stored -1000 reflects the headland''s general late Bronze Age occupation, not the fort. The field is emptied.", "value_page": null}]'::jsonb),
    ('611a3218-4df9-4018-8d46-c1e731f04b2a'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26a-s001:611a3218-4df9-4018-8d46-c1e731f04b2a:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=25260", "url": "https://www.megalithic.co.uk/article.php?sid=25260", "quote": "Type: Hillfort", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Brean_Down", "url": "https://en.wikipedia.org/wiki/Brean_Down", "quote": "There is also evidence of an Iron Age hill fort and prehistoric barrows and field systems", "outcome": "found"}, {"source": "https://www.burnham-on-sea.com/history/brean-down/", "url": "https://www.burnham-on-sea.com/history/brean-down/", "quote": "When the defences of the Hill Fort were constructed about 300 BC, iron had taken over from bronze as the main metal for tools.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The fortified site on Brean Down is a small promontory hillfort (a bank and rock-cut ditch across the ridge), described as a hill fort by every source, not a fortress or citadel; the canonical type for a hillfort is Fort.", "value_page": null}]'::jsonb),
    ('611a3218-4df9-4018-8d46-c1e731f04b2a'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Brean_Down', 'https://www.megalithic.co.uk/article.php?sid=25260', 'fields-wd1-2026-09-26a-s001:611a3218-4df9-4018-8d46-c1e731f04b2a:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Brean_Down'' -> ''https://www.megalithic.co.uk/article.php?sid=25260''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=25260", "url": "https://www.megalithic.co.uk/article.php?sid=25260", "quote": "Brean Down Hillfort Somerset", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/List_of_hillforts_and_ancient_settlements_in_Somerset", "url": "https://en.wikipedia.org/wiki/List_of_hillforts_and_ancient_settlements_in_Somerset", "quote": "Brean Down is a Bronze Age hillfort situated on a peninsula jutting out into the Bristol Channel", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the whole promontory (geology, wildlife, Roman temple, Victorian fort) and gives the hillfort one sentence; there is no Wikipedia article on the hillfort, and the Historic England and Somerset HER records cannot be read without a browser. The Megalithic Portal entry ''Brean Down Hillfort'' is a readable page about the hillfort itself, which Wikipedia''s Somerset hillfort list also names.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('672f18a4-e818-4367-b593-fe0432b134a7'::uuid, 'site_type', 'Cave Structures', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26a-s001:672f18a4-e818-4367-b593-fe0432b134a7:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Cave Structures'' -> ''Necropolis/tombs complex''', '[{"source": "https://en.wikipedia.org/wiki/Laguna_de_las_Momias", "url": "https://en.wikipedia.org/wiki/Laguna_de_las_Momias", "quote": "The tombs were housed in caves with paintings on the walls related to the mausoleums and containing indecipherable symbols.", "outcome": "found"}, {"source": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=530", "url": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=530", "quote": "el sitio está compuesto por seis mausoleos intactos y los cimientos de una séptima estructura, todos alineados en un estrecho abrigo natural dentro del acantilado.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0008)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as a row of six or seven Chachapoya mausoleums (chullpas) holding over 200 mummy bundles, built into a natural rock shelter in the cliff above the lake; it is a funerary complex of tombs rather than a cave site, so ''Necropolis/tombs complex'' replaces ''Cave Structures''.", "value_page": null}]'::jsonb),
    ('69dd4372-657e-4a25-99bf-fdc8614a9e97'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26a-s001:69dd4372-657e-4a25-99bf-fdc8614a9e97:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('69dd4372-657e-4a25-99bf-fdc8614a9e97'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26a-s001:69dd4372-657e-4a25-99bf-fdc8614a9e97:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "The only dated statement (4000-3600 BC) comes from the deleted Wikipedia stub and its mirrors (Archaeolist, everything.explained, Wikiwand), all one source family; no independent readable source dates the Peregonivka settlement.", "value_page": null}]'::jsonb),
    ('69dd4372-657e-4a25-99bf-fdc8614a9e97'::uuid, 'site_type', 'City/town/settlement', NULL, 'fields-wd1-2026-09-26a-s001:69dd4372-657e-4a25-99bf-fdc8614a9e97:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''City/town/settlement'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "Only the Wikipedia family (the Ukrainian village article citing a Google My Maps layer, and the English settlements list) and copies of the deleted English stub call Peregonivka a Trypillia settlement; no second independent source could be found.", "value_page": null}]'::jsonb),
