    ('7b747114-5587-42b6-816a-b701f791bd19'::uuid, 'period_start', '1', '-400', 'fields-wd1-2026-09-26a-s001:7b747114-5587-42b6-816a-b701f791bd19:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''1'' -> ''-400''', '[{"source": "https://antalyatouristinformation.com/things-to-do/history/lyrbe/", "url": "https://antalyatouristinformation.com/things-to-do/history/lyrbe/", "quote": "The ancient city of Lyrbe was founded on a hill as an acropolis in the 4th century BC.", "outcome": "found"}, {"source": "https://followinghadrian.com/2013/04/29/exploring-seleukeia-lyrbe-images-from-the-forgotten-city-of-pamphylia/", "url": "https://followinghadrian.com/2013/04/29/exploring-seleukeia-lyrbe-images-from-the-forgotten-city-of-pamphylia/", "quote": "Based on epigraphic evidence, it is assumed that the former city of Lyrbe had a long history, dating back to the Hellenistic period (330-30 BC).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "Antalya Tourist Information dates the foundation of Lyrbe as a hilltop acropolis to the 4th century BC and Following Hadrian traces the city back to the Hellenistic period (330-30 BC); the Antalya culture directorate adds that its oldest finds are Classical. The start therefore lies in the 500 BC - 1 AD bucket, not in the stored 1 - 500 AD bucket.", "value_page": null}]'::jsonb),
    ('7b747114-5587-42b6-816a-b701f791bd19'::uuid, 'site_type', 'Temple complex', 'City/town/settlement', 'fields-wd1-2026-09-26a-s001:7b747114-5587-42b6-816a-b701f791bd19:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Temple complex'' -> ''City/town/settlement''', '[{"source": "https://en.wikipedia.org/wiki/Lyrbe", "url": "https://en.wikipedia.org/wiki/Lyrbe", "quote": "was an ancient city and later episcopal see in the Roman province of Pamphylia Prima and is now a titular see.", "outcome": "found"}, {"source": "https://www.antalyakulturenvanteri.com/lyrbe/", "url": "https://www.antalyakulturenvanteri.com/lyrbe/", "quote": "Antalya ili, Manavgat ilçesi sınırları içerisinde, Bucakşeyhler Mahallesi''nin yaklaşık 1 km kuzeyinde, Helenistik Dönem''de kurulmuş bir Pamfilya kentidir.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls Lyrbe an ancient city and episcopal see and the Antalya cultural heritage inventory a Pamphylian city (kent) founded in the Hellenistic period, with an agora, baths, temples, churches and necropolis; the temples are parts of a city, so City/town/settlement replaces Temple complex.", "value_page": null}]'::jsonb),
