    ('7d2ffdf7-cc41-4c96-8544-12941eff6c2d'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Winnemucca_Lake', 'https://www.usgs.gov/publications/dating-north-americas-oldest-petroglyphs-winnemucca-lake-subbasin-nevada', 'fields-wd1-2026-09-26a-s001:7d2ffdf7-cc41-4c96-8544-12941eff6c2d:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Winnemucca_Lake'' -> ''https://www.usgs.gov/publications/dating-north-americas-oldest-petroglyphs-winnemucca-lake-subbasin-nevada''', '[{"source": "https://www.usgs.gov/publications/dating-north-americas-oldest-petroglyphs-winnemucca-lake-subbasin-nevada", "url": "https://www.usgs.gov/publications/dating-north-americas-oldest-petroglyphs-winnemucca-lake-subbasin-nevada", "quote": "On the west side of the Winnemucca Lake subbasin, Nevada, distinctive deeply carved meter-scale petroglyphs are closely spaced, forming panels on boulder-sized surfaces of a partially collapsed tufa mound.", "outcome": "found"}, {"source": "https://www.sciencedaily.com/releases/2013/08/130813121622.htm", "url": "https://www.sciencedaily.com/releases/2013/08/130813121622.htm", "quote": "The petroglyphs located at the Winnemucca Lake petroglyph site 35 miles northeast of Reno consist of large, deeply carved grooves and dots forming complex designs on several large limestone boulders", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is the article on the dry lake itself (the petroglyphs have no Wikipedia article of their own, only a redirect to a section of the lake article); the USGS page of the 2013 dating study is a scholarly page about this very petroglyph site, which the University of Colorado release also names.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
