    ('8c4d854b-55f3-4004-bc87-cffe5a431a2e'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Janabiyah', 'https://archiqoo.com/locations/janabiyah_burials.php', 'fields-wd1-2026-09-26a-s001:8c4d854b-55f3-4004-bc87-cffe5a431a2e:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Janabiyah'' -> ''https://archiqoo.com/locations/janabiyah_burials.php''', '[{"source": "https://archiqoo.com/locations/janabiyah_burials.php", "url": "https://archiqoo.com/locations/janabiyah_burials.php", "quote": "Al Janabiyah Burial Mound Field is a mound field located in Northern Governorate, Bahrain.", "outcome": "found"}, {"source": "https://culture.gov.bh/en/authority/CulturalHighlights/DBM/Descriptionandsignificanceoftheproperty/", "url": "https://culture.gov.bh/en/authority/CulturalHighlights/DBM/Descriptionandsignificanceoftheproperty/", "quote": "Janabiyah Burial Mound Field is a relatively small field.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored enwiki article is about the town of Janabiyah; the burial field has no Wikipedia article, and Archiqoo''s page is devoted to the Al Janabiyah Burial Mound Field itself, which the Bahraini heritage authority names as a component of the Dilmun Burial Mounds.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('9001cee0-cda8-4309-917f-c0bece02e5e6'::uuid, 'site_type', 'Amphitheatre', 'Theatre', 'fields-wd1-2026-09-26a-s001:9001cee0-cda8-4309-917f-c0bece02e5e6:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Amphitheatre'' -> ''Theatre''', '[{"source": "https://en.wikipedia.org/wiki/Kom_El_Deka", "url": "https://en.wikipedia.org/wiki/Kom_El_Deka", "quote": "The theatre is a small Roman theatre used for various forms of entertainment.", "outcome": "found"}, {"source": "https://egymonuments.gov.eg/archaeological-sites/kom-el-dikka/", "url": "https://egymonuments.gov.eg/archaeological-sites/kom-el-dikka/", "quote": "The centerpiece of the site is the well-preserved Roman Theater (Odeon), the only example of its kind in Egypt.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The monument is a small semicircular Roman theatre (odeon) with 13 tiers of seats, not an elliptical amphitheatre; Wikipedia and the Egyptian Ministry of Tourism and Antiquities both call it a Roman theatre, so the popular misnomer Amphitheatre is replaced by Theatre.", "value_page": null}]'::jsonb),
    ('9001cee0-cda8-4309-917f-c0bece02e5e6'::uuid, 'source_url', 'https://ask-aladdin.com/egypt-sites/greco-roman-monuments/romantheatre/', 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%85%D8%B3%D8%B1%D8%AD_%D8%A7%D9%84%D8%B1%D9%88%D9%85%D8%A7%D9%86%D9%8A_(%D8%A7%D9%84%D8%A5%D8%B3%D9%83%D9%86%D8%AF%D8%B1%D9%8A%D8%A9)', 'fields-wd1-2026-09-26a-s001:9001cee0-cda8-4309-917f-c0bece02e5e6:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://ask-aladdin.com/egypt-sites/greco-roman-monuments/romantheatre/'' -> ''https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%85%D8%B3%D8%B1%D8%AD_%D8%A7%D9%84%D8%B1%D9%88%D9%85%D8%A7%D9%86%D9%8A_(%D8%A7%D9%84%D8%A5%D8%B3%D9%83%D9%86%D8%AF%D8%B1%D9%8A%D8%A9)''', '[{"source": "https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%85%D8%B3%D8%B1%D8%AD_%D8%A7%D9%84%D8%B1%D9%88%D9%85%D8%A7%D9%86%D9%8A_(%D8%A7%D9%84%D8%A5%D8%B3%D9%83%D9%86%D8%AF%D8%B1%D9%8A%D8%A9)", "url": "https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%85%D8%B3%D8%B1%D8%AD_%D8%A7%D9%84%D8%B1%D9%88%D9%85%D8%A7%D9%86%D9%8A_(%D8%A7%D9%84%D8%A5%D8%B3%D9%83%D9%86%D8%AF%D8%B1%D9%8A%D8%A9)", "quote": "المسرح الروماني هو مسرح روماني قديم يقع بمنطقة كوم الدكة وسط مدينة الإسكندرية في مصر", "outcome": "found"}, {"source": "https://www.atentours.com/blogs/alexandria-attraction/roman-theatre-kom-el-dikka-alexandria", "url": "https://www.atentours.com/blogs/alexandria-attraction/roman-theatre-kom-el-dikka-alexandria", "quote": "The Roman Theatre of Kom El Dikka", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored ask-aladdin URL redirects to another page; the theatre has no English Wikipedia article of its own (Kom El Deka covers the whole quarter), but the Arabic Wikipedia article is about exactly this Roman theatre at Kom el-Dikka, which Aten Tours also names as the Roman Theatre of Kom El Dikka.", "value_page": {"lang": "ar", "problem": null, "resolved_title": "المسرح الروماني (الإسكندري