    ('9f5be838-53ab-48d8-9a1a-ac9597a87777'::uuid, 'site_type', 'City/town/settlement', 'Forum', 'fields-wd1-2026-09-26a-s001:9f5be838-53ab-48d8-9a1a-ac9597a87777:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''City/town/settlement'' -> ''Forum''', '[{"source": "https://en.wikipedia.org/wiki/Macellum_of_Pompeii", "url": "https://en.wikipedia.org/wiki/Macellum_of_Pompeii", "quote": "The Macellum of Pompeii was located on the Forum and, as the provision market", "outcome": "found"}, {"source": "https://www.gpsmycity.com/attractions/macellum-(provision-market)-27875.html", "url": "https://www.gpsmycity.com/attractions/macellum-(provision-market)-27875.html", "quote": "The Provision Market of Pompeii was built alongside the Forum to provide further space for the city’s growing central market.", "outcome": "found"}, {"source": "https://madainproject.com/macellum_of_pompeii", "url": "https://madainproject.com/macellum_of_pompeii", "quote": "Built in the second half of the second century BCE, this marketplace was strategically located on the north-east corner of the Roman Forum", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a single building, Pompeii''s provision market (marketplace) on the Forum, not a city or settlement; the canonical list has no market type, and Forum, the Roman public market square of which it formed the extension, is the closest specific type.", "value_page": null}]'::jsonb),
    ('b1410fda-e006-411f-a8ce-64513976d158'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26a-s001:b1410fda-e006-411f-a8ce-64513976d158:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b1410fda-e006-411f-a8ce-64513976d158'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26a-s001:b1410fda-e006-411f-a8ce-64513976d158:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "clear", "status": "MISSING", "reasoning": "Wet Withens has no dated start of its own: Wikipedia, the Megalithic Portal and stone-circles.org.uk call it only ''Bronze Age'', and the one source family with years, the Derbyshire HER, gives the generic Bronze Age span 2350-701 BC and the class date of excavated embanked circles (c. 2,400-1,000 BC), which straddles two buckets; nothing supports the stored Early Neolithic -4500, and no two independent sources date the start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('b1410fda-e006-411f-a8ce-64513976d158'::uuid, 'site_type', 'Henge', 'Stone circle', 'fields-wd1-2026-09-26a-s001:b1410fda-e006-411f-a8ce-64513976d158:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Henge'' -> ''Stone circle''', '[{"source": "https://her.derbyshire.gov.uk/Monument/MDR3889", "url": "https://her.derbyshire.gov.uk/Monument/MDR3889", "quote": "EMBANKED STONE CIRCLE (Bronze Age - 2350 BC to 701 BC)", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=304", "url": "https://www.megalithic.co.uk/article.php?sid=304", "quote": "Type: Stone Circle", "outcome": "found"}, {"source": "http://www.stone-circles.org.uk/stone/wetwithens.htm", "url": "http://www.stone-circles.org.uk/stone/wetwithens.htm", "quote": "the largest Bronze Age embanked stone circle in Derbyshire", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Derbyshire HER, the Megalithic Portal and stone-circles.org.uk all type Wet Withens as an (embanked) stone circle - a ring of orthostats on an earthen bank without a ditch; only Wikipedia''s lead calls it a henge while its own short description says stone circle, so the specific type is Stone circle, not Henge.", "value_page": null}]'::jsonb),
    ('b38b0f66-79cb-40db-9881-215e01196d2b'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26a-s001:b38b0f66-79cb-40db-9881-215e01196d2b:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b38b0f66-79cb-40db-9881-215e01196d2b'::uuid, 'period_start', '-3000', NULL, 'fields-wd1-2026-09-26a-s001:b38b0f66-79cb-40db-9881-215e01196d2b:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-3000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, Roman Britain and the Dorset HER all say the site has been in use since the (Late Upper) Palaeolithic, but that occupation is dated only in years before present (''12,500 years ago'', ''14,100 years ago'', ''12,500 years BP''); only one Wikipedia page gives a calendar year (''around 10,000 BC''). No two independent sources give the start as a year, and the stored -3000 contradicts the Palaeolithic start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('b9024baf-e614-498c-aa14-5c14d2c525b4'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26a-s001:b9024baf-e614-498c-aa14-5c14d2c525b4:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b9024baf-e614-498c-aa14-5c14d2c525b4'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26a-s001:b9024baf-e614-498c-aa14-5c14d2c525b4:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "clear", "status": "MISSING", "reasoning": "Only Archiqoo dates the site (''Its history dates back to the 1st century AD''); Wikipedia gives no start date, and the scholarship on Thibilis (Bertrandy on the city ''de Juba Ier'', 46-36 BC; the ASJP study of its Numidian-Punic phase) shows a pre-Roman Numidian town whose start no source dates, so no two sources support any start year.", "value_page": null}]'::jsonb),
    ('ba1d0bf4-260a-467e-adaa-2a53d13745aa'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26a-s001:ba1d0bf4-260a-467e-adaa-2a53d13745aa:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ba1d0bf4-260a-467e-adaa-2a53d13745aa'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26a-s001:ba1d0bf4-260a-467e-adaa-2a53d13745aa:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "clear", "status": "MISSING", "reasoning": "The sources date only the monuments around the Halos (the Polygonal wall after 548 BC, Hellenistic bases, the 548 BC votive pit), not the start of the Halos itself; no two sources give a start year, so the unsupported -500 is cleared.", "value_page": null}]'::jsonb),
    ('ba1d0bf4-260a-467e-adaa-2a53d13745aa'::uuid, 'site_type', 'Megalithic structures', 'Sacred site', 'fields-wd1-2026-09-26a-s001:ba1d0bf4-260a-467e-adaa-2a53d13745aa:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Megalithic structures'' -> ''Sacred site''', '[{"source": "https://en.wikipedia.org/wiki/Halos_(Delphi)", "url": "https://en.wikipedia.org/wiki/Halos_(Delphi)", "quote": "The Halos was a round open space close to the temple of Apollo in Delphi, where ancient rituals were being performed.", "outcome": "found"}, {"source": "https://www.clevelandart.org/articles/apollo-python-slayer", "url": "https://www.clevelandart.org/articles/apollo-python-slayer", "quote": "This foundation myth was ritually renewed during the Septerion festival at a circular area (the Halos) on the Sacred Way at the Delphi sanctuary, where Apollo’s triumph was reenacted by a boy impersonating the god.", "outcome": "found"}, {"source": "https://beyonder.travel/europe/greece/the-legend-and-reality-of-delphi-greece/", "url": "https://beyonder.travel/europe/greece/the-legend-and-reality-of-delphi-greece/", "quote": "Halos means “threshing floor”, which had special religious significance. Here, the Septerion is celebrated, a festival that was held every 8 years", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Halos is the circular open ritual space on the Sacred Way of Apollo''s sanctuary at Delphi where the Septerion was enacted (Wikipedia, Cleveland Museum of Art, Beyonder); it is no megalithic structure, and the most specific canonical type for such a cult place within the sanctuary is Sacred site.", "value_page": null}]'::jsonb),
    ('c050afab-2a46-4cbc-b795-b180b1d8172d'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26a-s001:c050afab-2a46-4cbc-b795-b180b1d8172d:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start -1500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c050afab-2a46-4cbc-b795-b180b1d8172d'::uuid, 'period_start', '-3000', '-1500', 'fields-wd1-2026-09-26a-s001:c050afab-2a46-4cbc-b795-b180b1d8172d:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-3000'' -> ''-1500''', '[{"source": "https://nichbelize.org/ia-sites/lamanai/", "url": "https://nichbelize.org/ia-sites/lamanai/", "quote": "Lamanai has one of the longest occupation spans dating from 1500 B.C. to the present", "outcome": "found"}, {"source": "https://lamanai.org.uk/index.html", "url": "https://lamanai.org.uk/index.html", "quote": "the Maya had established an agriculturally based settlement at Lamanai by or before 1500 B.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "Belize''s National Institute of Culture and History and the Lamanai Archaeological Project both date the start of occupation to c. 1500 BC, which falls in the 1500 - 500 BC bucket, not the stored 3000 - 1500 BC one.", "value_page": null}]'::jsonb),
    ('c0526e60-577b-4f28-9a07-e3c5739984bd'::uuid, 'site_type', 'Fortification', 'Fort', 'fields-wd1-2026-09-26a-s001:c0526e60-577b-4f28-9a07-e3c5739984bd:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''Fortification'' -> ''Fort''', '[{"source": "https://kennis.cultureelerfgoed.nl/index.php/Monumenten/46140", "url": "https://kennis.cultureelerfgoed.nl/index.php/Monumenten/46140", "quote": "Toen het expeditieleger vertrok, bleef een van de versterkingen staan: een fort, door de Romeinen castellum genoemd, op de plek van het huidige Castellumplein.", "outcome": "found"}, {"source": "https://geschiedenisvanzuidholland.nl/zien-en-doen/locaties/praetorium-agrippinae-in-valkenburg/", "url": "https://geschiedenisvanzuidholland.nl/zien-en-doen/locaties/praetorium-agrippinae-in-valkenburg/", "quote": "De Romeinen bouwden het eerste fort in 39 of 40 na Chr.", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/praetorium-agrippinae-valkenburg-zh/", "url": "https://www.livius.org/articles/place/praetorium-agrippinae-valkenburg-zh/", "quote": "name of a Roman fort and supply base on the Lower", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0008)", "decision": "replace", "status": "CONFLICT", "reasoning": "All sources describe Praetorium Agrippinae as a Roman auxiliary fort (castellum) on the Lower Rhine limes, rebuilt in seven phases; ''Fort'' is more specific than the generic ''Fortification''.", "value_page": null}]'::jsonb),
