    ('c62411bd-d3cb-4d12-af56-39488288dd40'::uuid, 'period_start', '-3000', '-4000', 'fields-wd1-2026-09-26a-s001:c62411bd-d3cb-4d12-af56-39488288dd40:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-3000'' -> ''-4000''', '[{"source": "http://art-and-archaeology.com/korea/seoul/am01.html", "url": "http://art-and-archaeology.com/korea/seoul/am01.html", "quote": "Amsadong is a neolithic site whose earliest level dates to the Fourth Millennium, ca. 4000 BC - 3000 BC.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Amsa-dong_Prehistoric_Site", "url": "https://en.wikipedia.org/wiki/Amsa-dong_Prehistoric_Site", "quote": "Around 4,000 B.C., people of the area lived inside huts with lowered floors called umjip.", "outcome": "found"}, {"source": "http://sunsa.gangdong.go.kr/site/eng/content/History_Preservation", "url": "http://sunsa.gangdong.go.kr/site/eng/content/History_Preservation", "quote": "In this campaign, a jade pendant was found for the first time at the site from a pit-dwelling dated 4,000 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Amsa-dong prehistoric settlement''s earliest level dates to the 4th millennium BC, c. 4000 BC (art-and-archaeology.com, Wikipedia, and the site''s own Gangdong-gu page with a pit-dwelling dated 4,000 BC); the stored -3000 is in the next bucket, and Wikidata''s -5000 is not supported by these sources.", "value_page": null}]'::jsonb),
    ('c8b957fb-37fa-46eb-84fd-39e572072d05'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Bent_Pyramid', 'https://it.wikipedia.org/wiki/Piramide_satellite_meridionale_di_Snefru', 'fields-wd1-2026-09-26a-s001:c8b957fb-37fa-46eb-84fd-39e572072d05:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Bent_Pyramid'' -> ''https://it.wikipedia.org/wiki/Piramide_satellite_meridionale_di_Snefru''', '[{"source": "https://it.wikipedia.org/wiki/Piramide_satellite_meridionale_di_Snefru", "url": "https://it.wikipedia.org/wiki/Piramide_satellite_meridionale_di_Snefru", "quote": "La piramide satellite meridionale di Snefru è la piramide accessoria del Complesso piramidale meridionale di Snefru più conosciuto con il nome di piramide romboidale", "outcome": "found"}, {"source": "https://www.guardians.net/egypt/pyramids/dahshur/Sneferu/TheBentPyramid.htm", "url": "https://www.guardians.net/egypt/pyramids/dahshur/Sneferu/TheBentPyramid.htm", "quote": "The satellite pyramid on the south side of the Bent pyramid had an interesting feature which is a precursor the Grand Gallery of the Great Pyramid.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the Bent Pyramid itself (another Wikidata item); the satellite pyramid''s own article is the Italian Wikipedia one linked from its Wikidata item Q3905572, and Guardian''s Egypt names the same satellite pyramid south of the Bent Pyramid.", "value_page": {"lang": "it", "problem": null, "resolved_title": "Piramide satellite meridionale di Snefru", "unreadable": false, "wikibase_item": "Q3905572"}}]'::jsonb),
    ('cb95c838-ea7e-485c-8c7f-4f00427c04e1'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Helg%C3%B6', 'https://www.megalithic.co.uk/article.php?sid=63813', 'fields-wd1-2026-09-26a-s001:cb95c838-ea7e-485c-8c7f-4f00427c04e1:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Helg%C3%B6'' -> ''https://www.megalithic.co.uk/article.php?sid=63813''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=63813", "url": "https://www.megalithic.co.uk/article.php?sid=63813", "quote": "The archaeological site on Helgö—also known as the \"Helgö Settlement\"—emerged around the 2nd century AD, though its roots extend back to the Bronze Age.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Helg%C3%B6", "url": "https://en.wikipedia.org/wiki/Helg%C3%B6", "quote": "The old trading town on Helgö began to emerge around the year 200 AD, 500 years before Birka at Björkö.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the island of Helgö (with sections on Kaggeholm Castle and more); the Megalithic Portal entry ''Helgö settlement'' is about the archaeological settlement itself, which Wikipedia independently names as the old trading town on Helgö.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('ce033c02-864e-45aa-8b32-f233dda3e043'::uuid, 'site_type', 'City/town/settlement', 'Monastery', 'fields-wd1-2026-09-26a-s001:ce033c02-864e-45aa-8b32-f233dda3e043:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''City/town/settlement'' -> ''Monastery''', '[{"source": "https://digitalgandhara.com/Ranigat", "url": "https://digitalgandhara.com/Ranigat", "quote": "It features a main stupa courtyard with monastic buildings to the south, a secondary monastery with a shrine and large stupa to the southwest, and a terrace of stupas to the west.", "outcome": "found"}, {"source": "https://doam.gov.pk/public/sites/2370", "url": "https://doam.gov.pk/public/sites/2370", "quote": "Archaeological Site - Stupa & Monastery", "outcome": "found"}, {"source": "https://www.islamabadscene.com/pakistans-cultural-treasure-documented-by-japanese-archaeologist/", "url": "https://www.islamabadscene.com/pakistans-cultural-treasure-documented-by-japanese-archaeologist/", "quote": "Ranigat is the largest Buddhist monastic complex in Gandhara.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0008)", "decision": "replace", "status": "CONFLICT", "reasoning": "Digital Gandhara, Pakistan''s Department of Archaeology and Museums and the report on the Kyoto University survey all describe Ranigat as a Buddhist monastic complex of stupa courts and monasteries; it is not a town, and its enclosure wall does not make it primarily a fortress, so ''Monastery'' is the most specific fitting type.", "value_page": null}]'::jsonb),
    ('d0fafe30-c48a-4939-8e97-af0ff2a10689'::uuid, 'period_name', '500 BC - 1 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26a-s001:d0fafe30-c48a-4939-8e97-af0ff2a10689:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start -3000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d0fafe30-c48a-4939-8e97-af0ff2a10689'::uuid, 'period_start', '-500', '-3000', 'fields-wd1-2026-09-26a-s001:d0fafe30-c48a-4939-8e97-af0ff2a10689:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-500'' -> ''-3000''', '[{"source": "https://www.kilmartin.org/why-excavate-rock-art", "url": "https://www.kilmartin.org/why-excavate-rock-art", "quote": "Torbhlaren is one of the few rock art sites in the landscape to have produced radiocarbon dates which suggest the cup and ring markings were made there through the Later Neolithic and the Bronze Age (c.3000 to 1200 BC).", "outcome": "found"}, {"source": "https://www.stonepages.com/ancient_scotland/sites/ballygow.htm", "url": "https://www.stonepages.com/ancient_scotland/sites/ballygow.htm", "quote": "3rd-2nd millennium BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The cup-and-ring marked rocks of Kilmartin Glen are Late Neolithic to Bronze Age, not Iron Age. Kilmartin Museum reports that radiocarbon dates from Torbhlaren, one of the few dated rock-art sites in the glen, put the carving at c. 3000-1200 BC, and Stone Pages dates the Ballygowan cup-and-ring rocks to the 3rd-2nd millennium BC, so the start falls in the 3000-1500 BC bucket. Historic Environment Scotland''s broader estimate (probably 3500-2500 BC) is not based on dates from the glen.", "value_page": null}]'::jsonb),
    ('d0fafe30-c48a-4939-8e97-af0ff2a10689'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Kilmartin_Glen', 'https://www.kilmartin.org/why-excavate-rock-art', 'fields-wd1-2026-09-26a-s001:d0fafe30-c48a-4939-8e97-af0ff2a10689:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Kilmartin_Glen'' -> ''https://www.kilmartin.org/why-excavate-rock-art''', '[{"source": "https://www.kilmartin.org/why-excavate-rock-art", "url": "https://www.kilmartin.org/why-excavate-rock-art", "quote": "During the Neolithic and Bronze Ages, people created thousands of carvings on rocky outcrops throughout Kilmartin Glen. Most of these carvings consist of dots, circles, and lines, commonly known as cup and ring markings.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "url": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "quote": "Kilmartin Glen has \"a remarkable concentration of some of the most impressive cup and ring decorated rock surfaces in Scotland\".", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about Kilmartin Glen as an area, with the rock art only as one section; the Kilmartin Museum page is about the cup and ring carvings throughout Kilmartin Glen themselves, and Wikipedia independently names the glen''s cup and ring decorated rock surfaces.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('dfc745b9-b361-4d9e-9f95-90bb2237c66d'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26a-s001:dfc745b9-b361-4d9e-9f95-90bb2237c66d:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('dfc745b9-b361-4d9e-9f95-90bb2237c66d'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26a-s001:dfc745b9-b361-4d9e-9f95-90bb2237c66d:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "clear", "status": "MISSING", "reasoning": "The site is a Middle Palaeolithic Neanderthal site of Marine Isotope Stage 3, dated by the Norfolk HER to c. 59,000-38,000 years ago and by Wikipedia''s Lynford Quarry article to about 60,000 years ago; only one source family (Wikipedia''s History of Norfolk, ''around 58,000 BC'') states it as a BC year, so no two independent sources date the start in readable form, and the stored -500 is certainly wrong - the field is emptied.", "value_page": null}]'::jsonb),
    ('ec4f5013-86b2-45a2-af61-d69b8f863d74'::uuid, 'site_type', 'City/town/settlement', 'Fort', 'fields-wd1-2026-09-26a-s001:ec4f5013-86b2-45a2-af61-d69b8f863d74:site_type', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''City/town/settlement'' -> ''Fort''', '[{"source": "https://romancastleford.blogspot.com/p/excavations-fort.html", "url": "https://romancastleford.blogspot.com/p/excavations-fort.html", "quote": "Castleford was known to be the site of a Roman fort called Lagentium, but only archaeological excavations could prove for certain where it was.", "outcome": "found"}, {"source": "https://www.discoverbritainstowns.co.uk/news/castelford-roman-fort-archaeology/", "url": "https://www.discoverbritainstowns.co.uk/news/castelford-roman-fort-archaeology/", "quote": "At Castleford they built the fort they called Lagentium.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "Lagentium is the Roman fort at Castleford (with a vicus outside it); the excavation pages and Discover Britain''s Towns both call it a Roman fort, so the most specific type is Fort, not a generic settlement.", "value_page": null}]'::jsonb),
