    ('f1b3fa7c-d237-4d82-8d06-831a376ce267'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Egyptian_sun_temple', 'https://de.wikipedia.org/wiki/Sonnenheiligtum_des_Niuserre', 'fields-wd1-2026-09-26a-s001:f1b3fa7c-d237-4d82-8d06-831a376ce267:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Egyptian_sun_temple'' -> ''https://de.wikipedia.org/wiki/Sonnenheiligtum_des_Niuserre''', '[{"source": "https://de.wikipedia.org/wiki/Sonnenheiligtum_des_Niuserre", "url": "https://de.wikipedia.org/wiki/Sonnenheiligtum_des_Niuserre", "quote": "Das Sonnenheiligtum des Niuserre ist ein altägyptisches Tempel-Bauwerk aus der Zeit der 5. Dynastie", "outcome": "found"}, {"source": "https://www.theancientconnection.com/megaliths/egypt/solar-temple-abu-gorab/", "url": "https://www.theancientconnection.com/megaliths/egypt/solar-temple-abu-gorab/", "quote": "The Solar Temple at Abu Gorab was originally known as the Sun Temple of Niuserre, a place of worship of the God Ra that was supposedly constructed during the fifth dynasty of the Old Kingdom, or sometime around 2400 BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is the generic Egyptian sun temple article (another Wikidata item); the temple has no English article of its own (Abu Gorab covers the locality), so its own German Wikipedia article, linked from its Wikidata item Q2009417, replaces it; The Ancient Connection names the same Sun Temple of Niuserre at Abu Gorab.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Sonnenheiligtum des Niuserre", "unreadable": false, "wikibase_item": "Q2009417"}}]'::jsonb),
