    ('f91af2e3-60fc-4c63-9622-05c4e3f4b1cd'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26a-s001:f91af2e3-60fc-4c63-9622-05c4e3f4b1cd:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start -500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('f91af2e3-60fc-4c63-9622-05c4e3f4b1cd'::uuid, 'period_start', '-1500', '-500', 'fields-wd1-2026-09-26a-s001:f91af2e3-60fc-4c63-9622-05c4e3f4b1cd:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''-1500'' -> ''-500''', '[{"source": "https://www.napoligrafia.it/monumenti/cimiteri/mariaPianto/mariaPianto01.htm", "url": "https://www.napoligrafia.it/monumenti/cimiteri/mariaPianto/mariaPianto01.htm", "quote": "Così fu scelta una grande grotta sulla collina di Poggioreale, un’antica cava di tufo usata già dai greci tra il V e il IV secolo a.C.", "outcome": "found"}, {"source": "https://derivesuburbane.it/luoghi-di-culto/chiese-abbandonate/chiesa-di-santa-maria-del-pianto/", "url": "https://derivesuburbane.it/luoghi-di-culto/chiese-abbandonate/chiesa-di-santa-maria-del-pianto/", "quote": "si tratta di antiche cave sotterranee da cui già nel V secolo a. C. i greci estraevano blocchi di tufo.", "outcome": "found"}, {"source": "https://it.wikipedia.org/wiki/Chiesa_di_Santa_Maria_del_Pianto_(Napoli)", "url": "https://it.wikipedia.org/wiki/Chiesa_di_Santa_Maria_del_Pianto_(Napoli)", "quote": "risalenti al V secolo a.C., furono usati in epoca greca come cave di tufo per la costruzione della città.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The ancient site at this point is the Greek tuff quarry found in 1987 beneath the forecourt of Santa Maria del Pianto on the Poggioreale cemetery hill, where the Greeks of Neapolis cut blocks for the city walls. Napoligrafia dates its use to the 5th-4th century BC, Derive Suburbane to already the 5th century BC, and the Italian Wikipedia to the 5th century BC, so the start is the 5th century BC (-500), in the 500 BC - 1 AD bucket, not c. 1500 BC.", "value_page": null}]'::jsonb),
    ('f91af2e3-60fc-4c63-9622-05c4e3f4b1cd'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Poggioreale_(Naples)', 'https://www.roadtvitalia.it/cava-greca-poggioreale-stata-danneggiata-dai-vandali/', 'fields-wd1-2026-09-26a-s001:f91af2e3-60fc-4c63-9622-05c4e3f4b1cd:source_url', 'fields-wd1-2026-09-26a-s001 (wd1-replace): ''https://en.wikipedia.org/wiki/Poggioreale_(Naples)'' -> ''https://www.roadtvitalia.it/cava-greca-poggioreale-stata-danneggiata-dai-vandali/''', '[{"source": "https://www.roadtvitalia.it/cava-greca-poggioreale-stata-danneggiata-dai-vandali/", "url": "https://www.roadtvitalia.it/cava-greca-poggioreale-stata-danneggiata-dai-vandali/", "quote": "La storia della Cava greca di Poggioreale", "outcome": "found"}, {"source": "https://grandenapoli.it/le-mura-della-napoli-greco-romana/", "url": "https://grandenapoli.it/le-mura-della-napoli-greco-romana/", "quote": "I blocchi venivano estratti da una vasta cava di età greca che si trova a Poggioreale", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia URL redirects to the article on the Poggioreale quarter, the district the quarry lies in; no encyclopedia article covers the quarry itself, while the Road TV Italia report is entirely about the Cava greca di Poggioreale under Santa Maria del Pianto, which Grande Napoli describes as the same Greek quarry.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('faab0d7b-1f66-45b9-8b1b-95697a3fc320'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26a-s001:faab0d7b-1f66-45b9-8b1b-95697a3fc320:period_name', 'fields-wd1-2026-09-26a-s001 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('faab0d7b-1f66-45b9-8b1b-95697a3fc320'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26a-s001:faab0d7b-1f66-45b9-8b1b-95697a3fc320:period_start', 'fields-wd1-2026-09-26a-s001 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "clear", "status": "MISSING", "reasoning": "The sources (Wikipedia, huancavelica.com, the MINCETUR inventory) call the walled settlement only ''pre-Hispanic''; none gives a construction or occupation date, so no start year can be sourced.", "value_page": null}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 158;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _fields_wd1_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _fields_wd1_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'lat' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'lon' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'geom' THEN p.new_value::geometry IS NOT DISTINCT FROM p.old_value::geometry OR p.new_value IS NULL
                WHEN 'period_start' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'site_type' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'source_url' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _fields_wd1_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.old_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.old_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.old_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.old_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row writes a value this lane owns (new value)
    SELECT count(*) INTO bad FROM _fields_wd1_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.new_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD')
                WHEN 'site_type' THEN p.new_value NOT IN ('City', 'Town', 'Village', 'Settlement', 'Urban', 'Villa', 'City/town/settlement', 'Residence/villa/farmhouse', 'City/town/settlement, Pyramid complex', 'Castle', 'Citadel', 'Fort', 'Fortress', 'Military', 'Wall', 'Gate', 'Fortress/citadel', 'Castle/palace', 'Gate/archway/bridge', 'Fortification', 'Church', 'Mosque', 'Temple', 'Monastery', 'Sacred site', 'Sanctuary', 'Religious', 'Temple complex', 'Church/cathedral', 'Minaret/tower', 'Stone cross', 'Cemetery', 'Necropolis', 'Tomb', 'Burial', 'Funerary', 'Necropolis/tombs complex', 'Barrow', 'Mound/tumulus', 'Cairn', 'Elongated skulls', 'Megalithic', 'Megalithic stones', 'Megalithic structures', 'Megalithic statues', 'Megalithic walls', 'Stone circle', 'Dolmen', 'Standing stone', 'Henge', 'Timber circle', 'Polygonal masonry', 'Cave', 'Cave Structures', 'Rock relief/carving', 'Rock art', 'Petroglyphs', 'Sculptured stone', 'Cave Structures, Rock art', 'Geoglyphs', 'Road', 'Bridge', 'Mine', 'Quarry', 'Infrastructure', 'Road/avenue/trackway', 'Reservoir/aqueduct/canal', 'Mine/quarry', 'Earthwork', 'Well', 'Aqueduct', 'Bath', 'Harbor', 'Port', 'Underwater structures', 'Shipwreck', 'Monument', 'Memorial', 'Stadium', 'Theater', 'Theatre', 'Forum', 'Palace', 'Pyramid complex', 'Museum', 'Amphitheatre', 'Scheduled monument', 'Heritage site', 'Archaeological site', 'Site', 'Ruin', 'Inscription', 'Natural feature', 'Impact crater', 'Geological interest', 'Magnetic anomaly', 'Unknown')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) write a value this lane does not own', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _fields_wd1_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WD1/structured-fields', '2026-09-26a_fields-wd1-s001', r.change_key, 'two_source', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'WD1 field correction: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _fields_wd1_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.new_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.new_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.new_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _fields_wd1_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-09-26a_fields-wd1-s001'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-26a_fields-wd1-s001'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: this run stamp journalled % row(s) outside unified_sites.(lat, lon, geom, period_start, period_name, site_type, source_url)', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) hold a geom that is not their point
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _fields_wd1_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM _fields_wd1_plan q WHERE q.site_id = p.site_id AND q.column_name IN ('lat', 'lon', 'geom')) AND u.geom IS DISTINCT FROM ST_SetSRID(ST_MakePoint(u.lon, u.lat), 4326);
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned site(s) hold a geom that is not their point', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) hold a period_name that is not the bucket of their period_start
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _fields_wd1_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM _fields_wd1_plan q WHERE q.site_id = p.site_id AND q.column_name IN ('period_start', 'period_name')) AND u.period_name IS DISTINCT FROM (CASE WHEN u.period_start IS NULL THEN NULL WHEN u.period_start < -4500 THEN '< 4500 BC' WHEN u.period_start < -3000 THEN '4500 - 3000 BC' WHEN u.period_start < -1500 THEN '3000 - 1500 BC' WHEN u.period_start < -500 THEN '1500 - 500 BC' WHEN u.period_start < 1 THEN '500 BC - 1 AD' WHEN u.period_start < 500 THEN '1 - 500 AD' WHEN u.period_start < 1000 THEN '500 - 1000 AD' WHEN u.period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END);
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD1 field correction: % planned site(s) hold a period_name that is not the bucket of their period_start', bad;
    END IF;

    RAISE NOTICE 'WD1 field correction: % of % planned cell(s) changed and journalled over 63 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-26a_fields-wd1-s001'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WD1/structured-fields'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-09-26a_fields-wd1-s001' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'lat' THEN u.lat IS NOT DISTINCT FROM l.new_value::double precision
                WHEN 'lon' THEN u.lon IS NOT DISTINCT FROM l.new_value::double precision
                WHEN 'geom' THEN u.geom IS NOT DISTINCT FROM l.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS NOT DISTINCT FROM l.new_value::integer
                WHEN 'period_name' THEN u.period_name IS NOT DISTINCT FROM l.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS NOT DISTINCT FROM l.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS NOT DISTINCT FROM l.new_value::text
                ELSE false END)
UNION ALL
SELECT 'curated rows whose period_name is not the bucket of period_start', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND period_name IS DISTINCT FROM (CASE WHEN period_start IS NULL THEN NULL WHEN period_start < -4500 THEN '< 4500 BC' WHEN period_start < -3000 THEN '4500 - 3000 BC' WHEN period_start < -1500 THEN '3000 - 1500 BC' WHEN period_start < -500 THEN '1500 - 500 BC' WHEN period_start < 1 THEN '500 BC - 1 AD' WHEN period_start < 500 THEN '1 - 500 AD' WHEN period_start < 1000 THEN '500 - 1000 AD' WHEN period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END)
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
